std::string StatusCodeToMessage(StatusCode code) {
    switch (code) {
        case OK:
            return "OK";
        case BadRequest:
            return "Bad Request";
        case Forbidden:
            return "Forbidden";
        case NotFound:
            return "Not Found";
        default:
            return "Unknown Status Code";
    }
}

std::uint32_t StatusCodeToInteger(StatusCode code) {
    return static_cast<std::uint32_t>(code);
}

std::string MethodToString(Method method) {
    switch (method) {
        case Method::Get:
            return "GET";
        case Method::Post:
            return "POST";
        case Method::Put:
            return "PUT";
        case Method::Patch:
            return "PATCH";
        case Method::Delete:
            return "DELETE";
        default:
            return "UNKNOWN";
    }
}

Method StringToMethod(std::string str) {
    if (str == "GET") return Method::Get;
    if (str == "POST") return Method::Post;
    if (str == "PUT") return Method::Put;
    if (str == "PATCH") return Method::Patch;
    if (str == "DELETE") return Method::Delete;
    throw std::invalid_argument("Invalid HTTP method: " + str);
}

std::string ContentTypeByFileName(std::string_view name) {
    static const std::unordered_map<std::string, std::string> content_types = {
        {".html", "text/html"},
        {".css", "text/css"},
        {".js", "application/javascript"},
        {".png", "image/png"},
        {".jpg", "image/jpeg"},
        {".gif", "image/gif"}
    };

    size_t dot_pos = name.rfind('.');
    if (dot_pos != std::string_view::npos) {
        auto it = content_types.find(name.substr(dot_pos));
        if (it != content_types.end()) {
            return it->second;
        }
    }
    return "application/octet-stream";
}

std::string DecodeURLEncodedCharacter(const std::string& str) {
    if (str.length() == 3 && str[0] == '%') {
        try {
            size_t pos = 0;
            unsigned int hex_value = std::stoul(str.substr(1, 2), &pos, 16);
            return std::string(1, static_cast<char>(hex_value));
        } catch (const std::invalid_argument& e) {
            throw std::invalid_argument("Invalid URL-encoded character: " + str);
        }
    } else if (str == "+"){
      return "";
    }else {
        throw std::invalid_argument("Invalid URL-encoded string format.");
    }
}

std::string DecodeURLEncodedString(const std::string& str) {
    std::string decoded_str;
    for (size_t i = 0; i < str.length(); ++i) {
        if (str[i] == '%') {
            decoded_str += DecodeURLEncodedCharacter(str.substr(i, 3));
            i += 2;
        } else if (str[i] == '+'){ 
          // '+' is decoded as space.
        }else{
            decoded_str += str[i];
        }
    }
    return decoded_str;
}

std::string HTMLPlaceholder(std::string_view key) {
    return "<" + std::string(key) + ">";
}

std::string PutParamIntoHTML(std::string html, const Parameters& params) {
    for (const auto& pair : params) {
        size_t pos = 0;
        std::string key = pair.first;
        while ((pos = html.find("<" + key + "", pos)) != std::string::npos) {
            html.replace(pos, key.length() + 2, pair.second);
            pos += pair.second.length();
        }
    }
    return html;
}

}
